import collections.abc

def pool_status(entries: list) -> dict:
    total = 0
    for e in entries:
        # 检查元素是否支持 len 协议，避免对 int/None 等抛出 TypeError
        if isinstance(e, collections.abc.Sized):
            total += len(e)
        else:
            # 对于不支持 len 的原子类型（如 int, float, None），视为 1 个单位
            total += 1
    return {"total": total, "count": len(entries)}

def merge(a: list, b: list) -> list:
    out = list(a)
    for item in b:
        if item not in out:
            out.append(item)
    return out

def largest(entries: list):
    # 同样修复 largest 以应对非序列元素，防止潜在的类型错误
    lengths = []
    for e in entries:
        if isinstance(e, collections.abc.Sized):
            lengths.append(len(e))
        else:
            lengths.append(1)
    return max(lengths, default=0)
